package com.greenlink.controller;import com.greenlink.dto.MessageView;import com.greenlink.security.AppUserPrincipal;import com.greenlink.service.MessageService;import java.util.*;import org.bson.types.ObjectId;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/messages") public class MessageController {private final MessageService s;public MessageController(MessageService s){this.s=s;} @PostMapping public ResponseEntity<MessageView> send(@AuthenticationPrincipal AppUserPrincipal p,@RequestBody Map<String,String> b){return ResponseEntity.status(201).body(s.send(new ObjectId(p.getId()),b.get("requestId"),b.get("content")));} @GetMapping("/{requestId}") public List<MessageView> history(@AuthenticationPrincipal AppUserPrincipal p,@PathVariable String requestId){return s.history(new ObjectId(p.getId()),new ObjectId(requestId));}}
